-- R1: primero la regla, después la reescritura
ALTER TABLE carritos SET (fillfactor = 90);
VACUUM FULL carritos;

-- R2
ALTER TABLE carritos SET (
  autovacuum_vacuum_threshold = 200,
  autovacuum_vacuum_scale_factor = 0.05,
  autovacuum_analyze_scale_factor = 0.02
);

-- R3
CREATE ROLE app_web LOGIN;
ALTER ROLE app_web SET statement_timeout = '15s';
ALTER ROLE app_web SET idle_in_transaction_session_timeout = '1min';

-- R4
ALTER SYSTEM SET log_min_duration_statement = '500ms';
ALTER SYSTEM SET log_autovacuum_min_duration = '5s';
ALTER SYSTEM SET log_line_prefix = '%m [%p] %q%u@%d/%a ';

-- R5
CREATE SCHEMA monitoreo;
CREATE VIEW monitoreo.tablas AS
SELECT c.relname AS tabla,
       pg_total_relation_size(c.oid) AS bytes_total,
       round(coalesce(o.umbral, current_setting('autovacuum_vacuum_threshold')::numeric)
             + coalesce(o.factor, current_setting('autovacuum_vacuum_scale_factor')::numeric)
               * c.reltuples::numeric) AS umbral_vacuum
FROM pg_class c
CROSS JOIN LATERAL (
  SELECT max(option_value) FILTER (WHERE option_name = 'autovacuum_vacuum_threshold')::numeric AS umbral,
         max(option_value) FILTER (WHERE option_name = 'autovacuum_vacuum_scale_factor')::numeric AS factor
  FROM pg_options_to_table(c.reloptions)
) AS o
WHERE c.relnamespace = 'public'::regnamespace AND c.relkind = 'r';

